def main():
    root = os.path.join(os.path.dirname(__file__), "..", "content")
    os.makedirs(root, exist_ok=True)
    per = {}
    fcs = []
    for t, front, back, sub in FC:
        per[t] = per.get(t, 0) + 1
        fcs.append({"id": f"fc-{t:02d}-{per[t]}", "topic": f"{t} {TOPICS[t]}", "front": front, "back": back, "source": src(t, sub)})
    per = {}
    mcqs = []
    for i, (t, q, opts, expl, sub) in enumerate(MCQ):
        per[t] = per.get(t, 0) + 1
        pos = i % 4  # balanced answer key
        o = opts[1:]
        o.insert(pos, opts[0])
        mcqs.append({"id": f"mcq-{t:02d}-{per[t]}", "topic": f"{t} {TOPICS[t]}", "question": q, "options": o,
                     "answer": pos, "explanation": expl, "source": src(t, sub)})
        assert mcqs[-1]["options"][pos] == opts[0]
    for name, data in (("flashcards.json", fcs), ("mcq.json", mcqs)):
        with open(os.path.join(root, name), "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
    print(f"wrote {len(fcs)} flashcards, {len(mcqs)} MCQs")

if __name__ == "__main__":
    main()
